import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const x=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md","lastUpdated":1786866352000}'),i={name:"faq/index.md"};function d(n,a,l,h,s,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="api-中转和手机远程控制有什么区别" tabindex="-1">API 中转和手机远程控制有什么区别？ <a class="header-anchor" href="#api-中转和手机远程控制有什么区别" aria-label="Permalink to &quot;API 中转和手机远程控制有什么区别？&quot;">​</a></h2><p>API 中转解决的是“让 Codex 通过统一 API 地址发送请求”；手机远程控制解决的是“离开电脑后继续从手机操作本地运行的 Codex”。两者可以分别使用，也可以组合使用：被控电脑上的 Codex 可以使用 API 中转配置。</p><h2 id="codex-和文件在哪里运行" tabindex="-1">Codex 和文件在哪里运行？ <a class="header-anchor" href="#codex-和文件在哪里运行" aria-label="Permalink to &quot;Codex 和文件在哪里运行？&quot;">​</a></h2><p>API 中转会转发 Codex 请求，具体请求内容取决于客户端和当前服务配置。手机远程控制的命令、文件和终端操作发生在你的电脑上，手机只负责发送操作和显示结果。</p><h2 id="为什么必须从-使用密钥-复制配置" tabindex="-1">为什么必须从“使用密钥”复制配置？ <a class="header-anchor" href="#为什么必须从-使用密钥-复制配置" aria-label="Permalink to &quot;为什么必须从“使用密钥”复制配置？&quot;">​</a></h2><p>控制台生成的配置会根据当前分组和认证模式输出正确组合，比复制旧教程更可靠。配置入口在 API 密钥列表的 <strong>使用密钥</strong>。</p><h2 id="api-key-可以多人共用吗" tabindex="-1">API Key 可以多人共用吗？ <a class="header-anchor" href="#api-key-可以多人共用吗" aria-label="Permalink to &quot;API Key 可以多人共用吗？&quot;">​</a></h2><p>不建议。为每台设备或每个项目创建独立密钥，便于限制额度、轮换凭据和定位用量。</p><h2 id="电脑端关闭后还能从手机操作吗" tabindex="-1">电脑端关闭后还能从手机操作吗？ <a class="header-anchor" href="#电脑端关闭后还能从手机操作吗" aria-label="Permalink to &quot;电脑端关闭后还能从手机操作吗？&quot;">​</a></h2><p>不能。电脑需要开机联网，电脑端也必须保持运行。</p><h2 id="如何移除一台电脑" tabindex="-1">如何移除一台电脑？ <a class="header-anchor" href="#如何移除一台电脑" aria-label="Permalink to &quot;如何移除一台电脑？&quot;">​</a></h2><p>进入设备列表，找到这台电脑并移除，然后退出电脑端。</p>',13)])])}const _=e(i,[["render",d]]);export{x as __pageData,_ as default};
